import{_ as t,o,c as d,ae as a}from"./chunks/framework.DQC_QtFV.js";const m=JSON.parse('{"title":"compose and data volumes","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/compose.md","filePath":"en/guide/compose.md","lastUpdated":1793162416000}'),s={name:"en/guide/compose.md"};function n(c,e,r,i,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="compose-and-data-volumes" tabindex="-1">compose and data volumes <a class="header-anchor" href="#compose-and-data-volumes" aria-label="Permalink to &quot;compose and data volumes&quot;">​</a></h1><p><code>compose.yaml</code> describes four services; one stack is one account. No port needs publishing except the console&#39;s 8080.</p><table tabindex="0"><thead><tr><th>Service</th><th>What it is</th></tr></thead><tbody><tr><td><code>qq</code></td><td>the chat client (official, unmodified, headless) plus the driver. It holds the ptrace capability for the one key read at first login and nothing else</td></tr><tr><td><code>console</code></td><td>the panel. The only service meant to be published; behind one password it fronts the driver API and the live view</td></tr><tr><td><code>bot</code></td><td>the assistant: one agent session, notes memory, and a review pass over every outbound message</td></tr><tr><td><code>sandbox</code></td><td>where the assistant&#39;s commands run: an exec server that drops every command to an unprivileged user, one volume, no secret of its own</td></tr></tbody></table><h2 id="where-the-data-lives" tabindex="-1">Where the data lives <a class="header-anchor" href="#where-the-data-lives" aria-label="Permalink to &quot;Where the data lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Host path</th><th>Mounted at</th><th>Holds</th></tr></thead><tbody><tr><td><code>./data/driver</code></td><td><code>/data/driver</code></td><td><code>secrets/db_key</code> (0600), <code>mirror.db</code>, <code>config.json</code></td></tr><tr><td><code>./data/bot</code></td><td><code>/data/bot</code></td><td><code>bot.db</code>, <code>pi/</code> (<code>auth.json</code> 0600), <code>secrets/</code>, <code>stickers/</code></td></tr><tr><td><code>./workspace</code></td><td><code>/workspace</code></td><td>the agent&#39;s files and the full copies of truncated output</td></tr><tr><td><code>./logs</code></td><td><code>/out</code></td><td>the <code>qq</code> container&#39;s own logs: <code>qq.log</code>, <code>keyx.log</code>, <code>novnc.log</code></td></tr><tr><td><code>qq_profile</code> (volume)</td><td><code>/home/qq/.config/QQ</code></td><td>the client&#39;s profile: login state, databases, image cache</td></tr><tr><td><code>qq_install</code> (volume)</td><td><code>/opt/QQ</code></td><td>the installed client build</td></tr></tbody></table><p><code>./data/bot</code>, <code>./workspace</code> and <code>./logs</code> belong to uid 1000 (see <a href="./quick-start.html">Quick start</a>); the two named volumes need nothing.</p><h2 id="the-workspace-and-the-sandbox" tabindex="-1">The workspace and the sandbox <a class="header-anchor" href="#the-workspace-and-the-sandbox" aria-label="Permalink to &quot;The workspace and the sandbox&quot;">​</a></h2><p><code>./workspace</code> is shared by the bot and the sandbox and by nothing else. The sandbox has no other mount, so it cannot read the mirror, <code>bot.db</code> or the client&#39;s files, and its only route to the internet is the bot&#39;s egress proxy: the sandbox sits on an internal compose network that has no route out of the stack, and the bot is the only other service on it. Which domains the proxy allows is reviewed in the 网络 card on the <a href="./console/safety.html">Safety</a> page.</p><h2 id="the-logs-may-contain-chat-content" tabindex="-1">The logs may contain chat content <a class="header-anchor" href="#the-logs-may-contain-chat-content" aria-label="Permalink to &quot;The logs may contain chat content&quot;">​</a></h2><p>The files under <code>./logs</code> are diagnostics the stack writes while it runs, and they may contain chat content, so keep them private and do not share them. The panel&#39;s <a href="./console/logs.html">Logs</a> page is a different thing: it folds the driver&#39;s, the bot&#39;s and the panel&#39;s own events into one filterable feed.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>Backing up is copying <code>./data</code>, <code>./workspace</code> and the two named volumes. Losing the client&#39;s profile (<code>qq_profile</code>) costs a new QR scan; losing <code>qq_install</code> costs one reinstall on the next start. The update steps are on <a href="./updating.html">Updating</a>.</p>',12)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
